// Устройство задано здесь: iPhone WebKit 390×844 (как при проверке 02.11); проект iphone по умолчанию 375.
// Цифры PIN и пароль НЕ вводим. Тест режима ребёнка пропущен (нет слота parent-b-auto, решение 08.11); гостевой — работает.
import { test, expect, devices } from '@playwright/test';
import { ChildSlot, goChildHome, saveSlot, slotState } from '../child-slot.helpers';
import { expectParentGate, expectParentZoneHidden, visibleText } from './session-auth.helpers';

/** Слот QA-B1 — НЕ выдан и не будет (решение 08.11); тест режима ребёнка ниже пропущен. */
const KID: ChildSlot = { slot: 'parent-b-auto', account: 'parent-b', childId: 'd956324c-5d7c-4837-b9da-324f69570be2', nickname: 'QA-B1' };

test.use({
  browserName: 'webkit',
  viewport: { width: 390, height: 844 },
  isMobile: true,
  hasTouch: true,
  deviceScaleFactor: 3,
  userAgent: devices['iPhone 13'].userAgent,
});

const SSO_RE = /google|apple|microsoft|facebook|azure|github|\bsso\b|גוגל|מיקרוסופט|משרד החינוך|הזדהות/i;

test.describe('Сессия и права — iPhone 390, гость', () => {
  test.use({ storageState: { cookies: [], origins: [] } });

  test('iPhone 390: /sign-in без кнопок внешнего входа @iphone @prod-safe #a337fd', async ({ page }) => {
    await page.goto('/sign-in');
    await expect(page.getByRole('button', { name: 'כניסה', exact: true }).filter({ visible: true }).first()).toBeVisible();
    await expect(page.getByRole('button', { name: SSO_RE }).filter({ visible: true })).toHaveCount(0);
    await expect(page.getByRole('link', { name: SSO_RE }).filter({ visible: true })).toHaveCount(0);
  });
});

test.describe('Сессия и права — iPhone 390, режим ребёнка', () => {
  // ПРОПУЩЕНО (решение пользователя 08.11, #8ca267): режим ребёнка на сервере «запирает» файл входа до PIN/пароля;
  // нужен отдельный слот QA-B1 (parent-b-auto), а его НЕ будет. parent-b.json в режим ребёнка не переводить.
  test.skip(true, 'нет слота parent-b-auto — пропущено по решению 08.11');
  test.use({ storageState: slotState(KID) });

  test.afterEach(async ({ page }) => {
    await saveSlot(page.context(), KID);
  });

  test('iPhone 390: ребёнок → «הורים» и /settings → Parent Gate @iphone #a337fd', async ({ page }) => {
    await goChildHome(page, KID);

    // TODO verify selector: на 390 «הורים» может быть в нижнем меню, а не в шапке.
    await visibleText(page, 'הורים').click();
    await expectParentGate(page);
    await expectParentZoneHidden(page);

    await page.goto('/settings');
    await expectParentGate(page);
    await expectParentZoneHidden(page);
  });
});
